arguments.command:
cd /testbed && python -c "
import sys
from tests import test_systemd

# List all test functions
test_funcs = [name for name in dir() if name.startswith('test_')]
print('Found systemd tests:', test_funcs)

# Run each one
for name in test_funcs:
    func = globals().get(name)
    if func:
        try:
            print(f'Running {name}...', end=' ')
            func()
            print('PASSED')
        except Exception as e:
            print(f'FAILED: {e}')
            import traceback
            traceback.print_exc()
"

